// The reading text of one section: what a reader sees, as opposed to the transcription.
//
// A port of reading() in the projects repo's dads-thesis/checks/assemble.py, which builds the
// assembled reading edition. The two scripts keep the same rules:
//
//   1. A bracketed transcription description ("[stamp: ...]", "[handwritten, top left: ...]",
//      "[front cover: ...]") describes the scan rather than being text of the thesis, so it is
//      removed. A description is recognised by its opening word (DESCRIPTORS below), never by its
//      length: the thesis's own bracketed text — citations "[3, 5]" and "[1, 32 ÷ 76]", the
//      bibliography's translated titles "[A method of ...]", degree glosses "[Dr Eng.]", intervals
//      "[-0.38, +0.6]" — is left alone whatever its word count.
//   2. "[handwritten: X]" and "[inserted above line: X]" are the author's own corrections to the
//      typescript, so X stays in the text and only the brackets go.
//   3. "[?:...]" and "[?]" mark an uncertain or defective reading, kept as printed; they are set
//      off as a span so the reader sees a transcriber's mark, and so that a "(T)" following one is
//      not read as a Markdown link.
//   4. A translator note "[TN: ...]" is lifted out of the text into a numbered endnote, and a
//      marker takes its place.
//
// Everything else that uses square brackets is untouched: LaTeX math ($[a, b]$), HTML comments
// (the scan page markers), inline code, Markdown links and images. Every removed span is returned
// in `stripped`, which scripts/pull-content.sh writes to content/stripped.txt so each pull can be
// read over for a span that was the author's own text.
//
// This module imports nothing, so scripts/stripped-report.ts can run it under plain node.

export interface Reading {
  text: string;
  notes: string[];
  stripped: string[];
}

// Spans that are opaque to every rule, in the order they are tried.
const OPAQUE = /<!--[\s\S]*?-->|\$\$[\s\S]+?\$\$|\\\[[\s\S]+?\\\]|\\\([\s\S]+?\\\)|\$[^$\n]+?\$|`[^`\n]*`/g;

// Private-use characters, which no text of the thesis carries.
const PLACEHOLDER = /(\d+)/g;

const TN = /^TN:\s*/;

// The author's own corrections, transcribed with the word they insert.
const INSERTION = /^(?:handwritten|inserted above line):\s*(.+)$/s;

// An uncertain or defective reading, kept as printed.
const UNSURE = /^\?(?::|$)/;

// The opening word of a transcription description, as notes/transcription-spec.md has the
// transcribers write them (the same list drives checks/assemble.py in the projects repo).
const DESCRIPTORS = [
  'front cover',
  'back cover',
  'rear',
  'inside',
  'pastedown',
  'label',
  'stamp',
  'handwritten',
  'blank page',
  'bleed-through',
  'dedication page',
  'title page',
  'verso',
  'inserted above line',
  'signature',
  'illegible',
  'library',
  'spine',
  'typed',
  'ex-libris',
  'barcode',
  'figure',
  'pieczątka',
  'podpis',
  'nieczytelne'
];
const DESCRIPTOR = new RegExp(`^(?:${DESCRIPTORS.join('|')})(?![\\p{L}-])`, 'iu');

// A transcription description: a span opening with one of the descriptor words (followed by a
// colon, comma or space), or a one-word marker such as [illegible] or [blank].
export function isTranscriptionDescription(content: string): boolean {
  const t = content.trim();
  if (t === '') return false;
  if (INSERTION.test(t)) return false;
  return DESCRIPTOR.test(t);
}

// The index of the `]` closing the `[` at `open`, counting nested brackets; -1 when unbalanced.
function closing(text: string, open: number): number {
  let depth = 0;
  for (let i = open; i < text.length; i++) {
    if (text[i] === '[') depth++;
    else if (text[i] === ']') {
      depth--;
      if (depth === 0) return i;
    }
  }
  return -1;
}

// Removing a span must not leave two spaces, or a space before punctuation, behind it.
function trimBeforeRemoval(before: string, next: string | undefined): string {
  return next === undefined || /[ \t.,;:!?)\n]/.test(next) ? before.replace(/[ \t]+$/, '') : before;
}

export function unsureMarker(inner: string): string {
  return `<span class="unsure" title="Transcriber's mark: an uncertain or defective reading, kept as printed">[${inner}]</span>`;
}

export function reading(markdown: string, noteMarker: (n: number) => string = (n) => `[${n}]`): Reading {
  const opaque: string[] = [];
  const masked = markdown.replace(OPAQUE, (m) => `${opaque.push(m) - 1}`);
  const restore = (s: string) => s.replace(PLACEHOLDER, (_, i: string) => opaque[Number(i)] ?? '');

  const notes: string[] = [];
  const stripped: string[] = [];
  let out = '';
  let i = 0;
  while (i < masked.length) {
    const open = masked.indexOf('[', i);
    if (open < 0) {
      out += masked.slice(i);
      break;
    }
    const close = closing(masked, open);
    if (close < 0) {
      out += masked.slice(i);
      break;
    }
    const inner = masked.slice(open + 1, close);
    const isLinkText = masked[open - 1] === '!' || masked[close + 1] === '(' || masked[close + 1] === '[' || masked[close + 1] === ':';
    const insertion = INSERTION.exec(restore(inner));
    if (!isLinkText && TN.test(inner)) {
      notes.push(restore(inner.replace(TN, '').trim()));
      out += masked.slice(i, open) + `\uE002${notes.length}\uE003`;
    } else if (!isLinkText && insertion) {
      out += masked.slice(i, open) + (insertion[1] ?? '').trim();
    } else if (!isLinkText && UNSURE.test(inner)) {
      out += masked.slice(i, open) + unsureMarker(inner);
    } else if (!isLinkText && isTranscriptionDescription(restore(inner))) {
      stripped.push(restore(masked.slice(open, close + 1)));
      out = trimBeforeRemoval(out + masked.slice(i, open), masked[close + 1]);
    } else {
      out += masked.slice(i, close + 1);
    }
    i = close + 1;
  }
  return { text: restore(placeMarkers(out, noteMarker, restore)).replace(/^[ \t]+$/gm, ''), notes, stripped };
}

// A note standing on a line of its own marks the paragraph before it: its marker goes to the end
// of the last line of text above (never a scan comment or a display equation), as in assemble.py.
function placeMarkers(text: string, noteMarker: (n: number) => string, restore: (s: string) => string): string {
  const lines = text.split('\n');
  for (let i = 0; i < lines.length; i++) {
    const m = /^[ \t]*\uE002(\d+)\uE003[ \t]*$/.exec(lines[i] ?? '');
    if (!m) continue;
    let j = i - 1;
    while (j >= 0 && (!(lines[j] ?? '').trim() || /^(<!--|\$\$|\\\[)/.test(restore(lines[j] ?? '').trim()))) j--;
    if (j >= 0) {
      const line = (lines[j] ?? '').replace(/[ \t]+$/, '');
      const marker = `\uE002${m[1]}\uE003`;
      // On a table row the marker goes into the last cell, not after the closing pipe.
      lines[j] = /^\|.*\|$/.test(line) ? line.replace(/[ \t]*\|$/, `${marker} |`) : line + marker;
      lines[i] = '';
    }
  }
  return lines.join('\n').replace(/\uE002(\d+)\uE003/g, (_, n: string) => noteMarker(Number(n)));
}
