// Markdown to HTML at build time, with the thesis's LaTeX typeset by KaTeX and its figures pointed
// at the downscaled copies scripts/pull-content.sh writes to static/figures/.
//
// The text is a transcription of a 1978 typescript, so before Markdown sees it the typewriter's
// layout is undone (typescript() below) and a few conventions of the transcription are turned into
// HTML (typography() below). checks/assemble.py in the projects repo applies the same rules to the
// printed editions; keep the two in step.

import katex from 'katex';
import { Marked, type TokenizerAndRendererExtension, type Tokens } from 'marked';

function tex(source: string, displayMode: boolean): string {
  return katex.renderToString(source.trim(), { displayMode, throwOnError: false });
}

interface MathToken extends Tokens.Generic {
  text: string;
}

// $$ ... $$ or \[ ... \] standing as its own block.
const blockMath: TokenizerAndRendererExtension = {
  name: 'blockMath',
  level: 'block',
  start: (src) => src.match(/\$\$|\\\[/)?.index,
  tokenizer(src) {
    const m = /^(?:\$\$([\s\S]+?)\$\$|\\\[([\s\S]+?)\\\])[ \t]*(?:\n|$)/.exec(src);
    if (!m) return undefined;
    return { type: 'blockMath', raw: m[0], text: m[1] ?? m[2] ?? '' };
  },
  renderer: (token) => `<div class="math-display">${tex((token as MathToken).text, true)}</div>\n`
};

// $ ... $ or \( ... \) inside a paragraph. A $ followed by a space or a digit-and-space is a price
// or a stray dollar sign, not math.
const inlineMath: TokenizerAndRendererExtension = {
  name: 'inlineMath',
  level: 'inline',
  start: (src) => src.match(/\$|\\\(/)?.index,
  tokenizer(src) {
    const m = /^(?:\$\$([\s\S]+?)\$\$|\$(?!\s)([^$\n]+?)(?<!\s)\$|\\\(([\s\S]+?)\\\))/.exec(src);
    if (!m) return undefined;
    const display = m[1] !== undefined;
    return { type: 'inlineMath', raw: m[0], text: m[1] ?? m[2] ?? m[3] ?? '', display };
  },
  renderer: (token) => tex((token as MathToken).text, Boolean((token as MathToken)['display']))
};

const FIGURE = /(rys-\d+)\.(?:png|jpe?g)$/i;

// The site path of a figure the text links to, or null for any other image.
export function figurePath(href: string): string | null {
  const m = FIGURE.exec(href);
  return m ? `/figures/${m[1]?.toLowerCase()}.png` : null;
}

function escapeAttr(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
}

// English keys to the Polish lettering inside a figure: rys-NN -> [{pl, en}, ...], from
// notes/figure-labels/*.json in the projects repo.
export type FigureKeys = Record<string, { pl: string; en: string }[]>;

export interface RenderOptions {
  figureKeys?: FigureKeys;
}

// Spans that no text rule may touch: math, HTML comments, inline code, HTML tags.
const OPAQUE = /<!--[\s\S]*?-->|\$\$[\s\S]+?\$\$|\\\[[\s\S]+?\\\]|\\\([\s\S]+?\\\)|\$(?!\s)[^$\n]+?(?<!\s)\$|`[^`\n]*`|<[^>\n]+>/g;

// Applies fn to the text between opaque spans.
function outsideMath(markdown: string, fn: (text: string) => string): string {
  let out = '';
  let last = 0;
  for (const m of markdown.matchAll(OPAQUE)) {
    out += fn(markdown.slice(last, m.index)) + m[0];
    last = m.index + m[0].length;
  }
  return out + fn(markdown.slice(last));
}

// The transcription keeps the typescript's layout: each paragraph opens with a five-space indent,
// columns of values or index entries are lined up with spaces, and a word broken at the right
// margin ends its line with a hyphen. In Markdown an indent of four spaces is a code block, so
// indents come off; a run of indented lines is a column and keeps its line breaks; a hyphen that
// breaks a word is removed and the word rejoined ("kompensa-" / "cję" -> "kompensację"), while
// the typist's double hyphen marks a real compound ("naukowo--" / "techniczny" -> "naukowo-techniczny").
export function typescript(markdown: string): string {
  const lines = markdown.split('\n');
  const out: string[] = [];
  for (let i = 0; i < lines.length; i++) {
    let line = lines[i] ?? '';
    const indented = /^ {4,}\S/.test(line);
    if (indented) {
      const nextIndented = /^ {4,}\S/.test(lines[i + 1] ?? '');
      line = line.trimStart() + (nextIndented ? '  ' : '');
    } else if (/^[ \t]+\S/.test(line)) {
      line = line.trimStart();
    }
    out.push(line);
  }
  let text = out.join('\n');
  // A hyphen at the end of a line, between two letters, is the typewriter's word break — except
  // inside a list of figure labels or a table, where lines are items, not a broken paragraph.
  text = text.replace(/(\p{L})--\n[ \t]*(?=\p{Ll})/gu, '$1-');
  text = text.replace(/(\p{L})-\n[ \t]*(?=\p{Ll})/gu, '$1');
  return text;
}

// Conventions of the transcription outside math: a footnote mark typed as a superscript, "^{1}"
// in the English or "^{1/}" as the typescript has it; a subscript typed a half line below,
// "X_{o}" or "X_1", in captions, labels and notes.
export function typography(markdown: string): string {
  return outsideMath(markdown, (text) => {
    let t = text.replace(/\^\{([^}]{1,6})\}/g, '<sup>$1</sup>');
    t = t.replace(/(?<=\p{L})_\{([^}]{1,6})\}/gu, '<sub>$1</sub>');
    t = t.replace(/\b([A-Za-zδΔ]{1,3})_([A-Za-z0-9]{1,3})\b/g, '$1<sub>$2</sub>');
    return t;
  });
}

// A figure in the transcription is the image (its caption as the alt text), then the list of the
// lettering inside the drawing, then the caption again as the typescript prints it. The reader
// gets the image with its caption once, and under it the English key to the lettering.
const FIGURE_IMAGE = /^(!\[[^\n]*\]\(([^)\n]*)\))[ \t]*\n/gm;
const LABELS = /^\n(?:Labels|Etykiety|Oznaczenia):\n(?:- [^\n]*\n)+/;

function figureBlocks(markdown: string, keys: FigureKeys): string {
  let out = '';
  let last = 0;
  for (const m of markdown.matchAll(FIGURE_IMAGE)) {
    const [whole, image = '', href = ''] = m;
    const id = FIGURE.exec(href)?.[1]?.toLowerCase();
    let end = m.index + whole.length;
    const labels = LABELS.exec(markdown.slice(end));
    if (labels) end += labels[0].length;
    // The caption repeated under the labels, with its continuation lines, up to a blank line or a
    // translator note: only the paragraph that opens with this figure's own number.
    const number = id ? Number(id.slice(4)) : NaN;
    const caption = new RegExp(`^\\n(?:Fig|Rys)\\.? ${number}\\.[^\\n]*\\n(?:(?!\\[TN:)[^\\n]+\\n)*`).exec(markdown.slice(end));
    if (caption) end += caption[0].length;
    // A translator note on the dropped caption keeps its marker, set under the figure.
    const markers = (markdown.slice(m.index + whole.length, end).match(/<sup class="tn"[\s\S]*?<\/sup>/g) ?? []).join('');
    const key = id ? (keys[id] ?? []) : [];
    const keyLine = key.length > 0 || markers ? `\n<p class="figkey">${key.length > 0 ? `<b>Labels:</b> ${key.map((l) => `<i>${l.pl}</i> = ${l.en}`).join('; ')}` : ''}${markers}</p>\n` : '';
    out += markdown.slice(last, m.index) + `${image}\n${keyLine}\n`;
    last = end;
  }
  return out + markdown.slice(last);
}

const marked = new Marked({
  async: false,
  gfm: true,
  extensions: [blockMath, inlineMath],
  renderer: {
    image({ href, text, tokens }: Tokens.Image) {
      const src = figurePath(href) ?? href;
      const caption = this.parser.parseInline(tokens ?? marked.Lexer.lexInline(text));
      return `<figure><img class="figure" src="${escapeAttr(src)}" alt="${escapeAttr(text.replace(/<[^>]+>/g, ''))}" loading="lazy" /><figcaption>${caption}</figcaption></figure>`;
    },
    // A paragraph holding only a figure is the figure itself.
    paragraph({ tokens }: Tokens.Paragraph) {
      const html = this.parser.parseInline(tokens);
      return /^<figure>[\s\S]*<\/figure>$/.test(html.trim()) ? `${html}\n` : `<p>${html}</p>\n`;
    },
    // The page's own <h1> is the chapter title ("# ..." in the text); the subsections start at <h2>.
    heading({ tokens, depth }: Tokens.Heading) {
      const level = Math.min(Math.max(depth, 2), 6);
      return `<h${level}>${this.parser.parseInline(tokens)}</h${level}>\n`;
    }
  }
});

export function renderMarkdown(markdown: string, options: RenderOptions = {}): string {
  return marked.parse(typography(figureBlocks(typescript(markdown), options.figureKeys ?? {}))) as string;
}

export function renderInline(markdown: string): string {
  return marked.parseInline(typography(markdown)) as string;
}
